selector_to_html = {"a[href=\"#interpretation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Interpretation<a class=\"headerlink\" href=\"#interpretation\" title=\"Link to this heading\">\u00b6</a></h2><p>This optimisation only varies mixture ratio. Chamber pressure, thrust, area ratio, characteristic length, propellant choice, and inlet temperatures are fixed. The result is therefore the mixture ratio that maximises ideal vacuum performance for this design point.</p>", "a[href=\"../autoapi/pyskyfire/viz/plot_regen/PlotContour.html#pyskyfire.viz.plot_regen.PlotContour\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.plot_regen.PlotContour\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.plot_regen.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PlotContour</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"o\"><span class=\"pre\">*</span></span><span class=\"n\"><span class=\"pre\">contours</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">Any</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">show_labels</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">show_input_points</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">False</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">interpolation_points</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#int\" title=\"(in Python v3.15)\"><span class=\"pre\">int</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">500</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">title</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'Contour</span> <span class=\"pre\">Profiles'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">template</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'plotly_white'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <a class=\"reference internal\" href=\"../autoapi/pyskyfire/viz/core/PlotBase.html#pyskyfire.viz.core.PlotBase\" title=\"pyskyfire.viz.core.PlotBase\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">pyskyfire.viz.core.PlotBase</span></code></a></p><p>Plot bell-nozzle or toroidal-aerospike contours, mirrored about the x-axis.</p><p>Classic contours are sampled through their <code class=\"docutils literal notranslate\"><span class=\"pre\">r(x)</span></code> method when present.\nSet <code class=\"docutils literal notranslate\"><span class=\"pre\">show_input_points=True</span></code> to overlay the original input stations as\n<code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code> markers; <code class=\"docutils literal notranslate\"><span class=\"pre\">interpolation_points</span></code> controls the line resolution.\nIf a contour has a .name attribute, it\u2019s used for the legend label.</p></dd>", "a[href=\"../autoapi/pyskyfire/regen/contour/Contour.html#pyskyfire.regen.contour.Contour\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.contour.Contour\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.contour.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Contour</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">xs</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rs</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chamber_angle</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nozzle_angle</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Inner hot-gas contour of a bell-type rocket engine.</p><p>Represents the geometric wall line from the start of the chamber to\nthe nozzle exit, providing local areas, slopes, and radii.</p><p class=\"rubric\">Notes</p><p>This class is used by higher-level objects such as\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">CoolingCircuit</span></code> and\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">ThrustChamber</span></code>.</p></dd>", "a[href=\"#optimised-contour\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Optimised contour<a class=\"headerlink\" href=\"#optimised-contour\" title=\"Link to this heading\">\u00b6</a></h2><p>As a curiosity, after finding the optimum mixture ratio, we can easily find and plot a corresponding contour.</p>", "a[href=\"#objective\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Objective<a class=\"headerlink\" href=\"#objective\" title=\"Link to this heading\">\u00b6</a></h2><p>The mixture ratio is defined as:</p>", "a[href=\"#optimisation-curve\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Optimisation curve<a class=\"headerlink\" href=\"#optimisation-curve\" title=\"Link to this heading\">\u00b6</a></h2><p>The curve below shows the vacuum specific impulse calculated over the mixture-ratio range. The marker shows the optimum found by the optimiser.</p>", "a[href=\"#optimise-mixture-ratio\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Optimise mixture ratio<a class=\"headerlink\" href=\"#optimise-mixture-ratio\" title=\"Link to this heading\">\u00b6</a></h1><p>This how-to finds the oxidizer-to-fuel mixture ratio that gives the highest vacuum specific impulse for a fixed engine design point.</p><p>The example uses:</p>", "a[href=\"#run-the-optimisation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Run the optimisation<a class=\"headerlink\" href=\"#run-the-optimisation\" title=\"Link to this heading\">\u00b6</a></h2><p>Run the full script at: <a class=\"reference external\" href=\"https://github.com/ask-hovik/pyskyfire/blob/main/examples/MR_optimisation/MR_opt.py\"><code class=\"docutils literal notranslate\"><span class=\"pre\">examples/MR_optimisation/MR_opt.py</span></code></a></p><p>The central optimisation step is:</p>", "a[href=\"../autoapi/pyskyfire/regen/contour/index.html#pyskyfire.regen.contour.generate_contour\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.contour.generate_contour\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.contour.</span></span><span class=\"sig-name descname\"><span class=\"pre\">generate_contour</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">r_t</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">area_ratio</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">r_c</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">L_c</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">V_c</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">eps_c</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">AR_c</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">theta_conv</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">45</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">theta_div</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">15</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nozzle</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'rao'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">R_1f</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.5</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">R_2f</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.5</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">R_3f</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.382</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length_fraction</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.8</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">angle_input</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'degrees'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">export_tikz</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">False</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Generate a chamber and nozzle contour using four input modes.</p><p>Exactly one of the following input combinations must be provided:</p><p class=\"rubric\">Notes</p><p>In the flow direction, the curvature factors occur in the order\n<code class=\"docutils literal notranslate\"><span class=\"pre\">R_2f</span></code> (chamber fillet), <code class=\"docutils literal notranslate\"><span class=\"pre\">R_1f</span></code> (throat entrance), then <code class=\"docutils literal notranslate\"><span class=\"pre\">R_3f</span></code>\n(throat exit). All three scale the throat radius <code class=\"docutils literal notranslate\"><span class=\"pre\">r_t</span></code>.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
